/**
 * One page per rule, generated by the site build from rule metadata alone. Issue #59.
 *
 * The expected rule set is never typed here: it is imported from the live registries, the same
 * sets the SARIF output and --explain draw from. Two directions are checked, so a page that
 * exists for no rule fails just as a rule with no page does. Page content is asserted against
 * the rule's own metadata, so a page that repeats a neighbour's why fails.
 *
 * The site root is never restated either: it is read out of the sitemap the build emitted,
 * which is the same URL test/pages-seo.test.mjs pins.
 */
import { test } from "node:test";
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { mkdtempSync, existsSync, readdirSync, readFileSync, rmSync, statSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { allRules } from "../src/index.js";
import { commitRules } from "../src/commits.js";
import { renderSarif } from "../src/sarif.js";
import { rulePageUrl, ruleHelpText, SITE_ROOT } from "../src/rule-pages.js";
import { explain } from "../src/cli.js";
import type { Rule } from "../src/doc.js";

const ROOT = process.cwd();
const BUILD = join(ROOT, "scripts", "playground-build.mjs");

/** Every rule the SARIF output and --explain can both name. */
const ruleSet: Rule[] = [...allRules(), ...commitRules];

const site = mkdtempSync(join(tmpdir(), "slop-rulepages-"));
const built = spawnSync(process.execPath, [BUILD, "--out", join(site, "site")], { encoding: "utf8" });
assert.equal(built.status, 0, `playground-build failed:\n${built.stdout}\n${built.stderr}`);
const pageFor = (id: string): string => join(site, "site", "rules", id, "index.html");
const pageText = (id: string): string => {
  // An assertion, never an ENOENT: a missing page is the defect this suite exists to catch.
  assert.ok(existsSync(pageFor(id)), `${id}: the build wrote no page at rules/${id}/index.html`);
  return readFileSync(pageFor(id), "utf8");
};
test.after(() => rmSync(site, { recursive: true, force: true }));

/** The site root, read from the emitted sitemap rather than restated. */
const siteRoot = /<loc>([^<]+)<\/loc>/.exec(readFileSync(join(site, "site", "sitemap.xml"), "utf8"))![1]!;

/** The one spelling of HTML escaping, the same `& < > " '` set any escaper uses. */
const esc = (text: string): string =>
  text.replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;").replaceAll("'", "&#39;");

test("the rule registries resolve to a non-empty set", () => {
  // A guard, not decoration: with an empty registry (or a build that emitted nothing) the set
  // assertions below would hold trivially and prove nothing.
  assert.ok(ruleSet.length > 0, "the live registries resolved to an empty rule set");
});

test("every rule has a page, and no page exists for a rule that does not", () => {
  const missing = ruleSet.filter((rule) => !existsSync(pageFor(rule.id))).map((rule) => rule.id);
  assert.deepEqual(missing, [], `no page for ${missing.join(", ")}`);
  // Exclusivity: a page whose id is not a rule id is a page nothing links to honestly.
  const extra: string[] = [];
  for (const id of readdirRules()) {
    if (!ruleSet.some((rule) => rule.id === id)) extra.push(id);
  }
  assert.deepEqual(extra, [], `a page exists for ${extra.join(", ")}, which is not a rule`);
});

/** The ids that have a page, read back out of the emitted tree. */
function readdirRules(): string[] {
  const out: string[] = [];
  const stack = ["rules"];
  while (stack.length) {
    const dir = stack.pop()!;
    for (const name of readdirSync(join(site, "site", dir))) {
      const rel = `${dir}/${name}`;
      if (statSync(join(site, "site", rel)).isDirectory()) stack.push(rel);
      else if (name === "index.html") out.push(rel.slice("rules/".length, -"/index.html".length));
    }
  }
  return out.sort();
}

test("every page says what its rule says: title, severity, source, why, example, ignoreWhen", () => {
  for (const rule of ruleSet) {
    const html = pageText(rule.id);
    // The example fields can end in a newline; the pages quote them trimmed, the way --explain
    // prints them, so the expectation is trimmed the same way. Nothing else is altered. The
    // severity oracle is anchored to the severity line, so the word appearing elsewhere in a
    // rule's prose cannot stand in for it.
    for (const field of [rule.id, rule.title, rule.why, rule.source, rule.example.before, rule.example.after, rule.ignoreWhen, `severity: ${rule.severity}`]) {
      assert.ok(html.includes(esc(field.trimEnd())), `${rule.id}: the page is missing ${JSON.stringify(field.slice(0, 60))}`);
    }
    assert.ok(html.includes(`<title>`), `${rule.id}: no title`);
  }
});

test("a page carries no em or en dash of its own, quoted examples aside", () => {
  for (const rule of ruleSet) {
    const prose = pageText(rule.id).replace(/<pre>[\s\S]*?<\/pre>/g, "");
    assert.ok(!/[—–]/.test(prose), `${rule.id}: the page ships a dash outside the quoted example`);
  }
});

test("every SARIF rule carries its page URL and help text and markdown from its own metadata", () => {
  const log = JSON.parse(renderSarif([], ruleSet, "0.0.0")) as {
    runs: Array<{ tool: { driver: { rules: Array<{ id: string; helpUri?: string; help?: { text?: string; markdown?: string } }> } } }>;
  };
  const descriptors = log.runs[0]!.tool.driver.rules;
  assert.deepEqual(
    descriptors.map((r) => r.id).sort(),
    ruleSet.map((r) => r.id).sort(),
    "the SARIF rule list and the registries disagree",
  );
  const helpUris = descriptors.map((r) => r.helpUri);
  assert.deepEqual(new Set(helpUris).size, helpUris.length, "two rules share a helpUri");
  for (const rule of ruleSet) {
    const descriptor = descriptors.find((r) => r.id === rule.id)!;
    // The helpUri is the page's own URL: the site root from the emitted sitemap, then the page
    // path the build actually wrote for this id.
    assert.equal(descriptor.helpUri, `${siteRoot}rules/${rule.id}/`, `${rule.id}: helpUri is not the page URL`);
    // And the far end of that URL is the page the build emitted, carrying this rule's title.
    assert.ok(pageText(rule.id).includes(esc(rule.title)), `${rule.id}: the page at the helpUri does not name the rule`);
    for (const format of ["text", "markdown"] as const) {
      const help = descriptor.help?.[format];
      assert.equal(typeof help, "string", `${rule.id}: help.${format} is missing`);
      // Line by line, because the plain-text help indents each line of a field, which breaks
      // the raw string at a multi-line example's blank line. Every line of the field has to be
      // there, so a help string carrying another rule's material still fails.
      for (const field of [rule.title, rule.why, rule.source, rule.example.before, rule.example.after, rule.ignoreWhen]) {
        const lines = field.trimEnd().split("\n").filter((line) => line.trim() !== "");
        assert.ok(lines.every((line) => help!.includes(line)), `${rule.id}: help.${format} is missing ${JSON.stringify(field.slice(0, 60))}`);
      }
    }
  }
});

test("the page URL embeds the rule id verbatim", () => {
  // The URL must not be slugified or case-folded: the registry is lowercase today, and this
  // guard is for the day it is not, when a folded or slugified id would point at a page the
  // build never wrote.
  assert.equal(rulePageUrl("Dash"), `${SITE_ROOT}rules/Dash/`);
});

test("the plain-text help is --explain, byte for byte", () => {
  // docs/SARIF.md states help.text carries the same material --explain prints; the property is
  // pinned as equality so the two renderers cannot drift apart silently.
  for (const rule of ruleSet) {
    assert.equal(ruleHelpText(rule), explain(rule), `${rule.id}: help.text and --explain disagree`);
  }
});

test("help.markdown links the Wikipedia source a page can only name", () => {
  // The page renders the source as text (the page contract forbids a third-party link), so the
  // clickable citation lives in the SARIF help markdown instead.
  const log = JSON.parse(renderSarif([], ruleSet, "0.0.0"));
  for (const rule of ruleSet) {
    if (!rule.source.startsWith("Wikipedia,")) continue;
    const descriptor = log.runs[0].tool.driver.rules.find((r: { id: string }) => r.id === rule.id);
    assert.ok(descriptor, `${rule.id}: no SARIF descriptor`);
    const markdown: unknown = descriptor.help?.markdown;
    assert.equal(typeof markdown, "string", `${rule.id}: help.markdown is missing`);
    assert.match(markdown as string, /\[([^\]]+)\]\(https:\/\/en\.wikipedia\.org\/wiki\/[^)]+\)/, `${rule.id}: help.markdown does not link the source`);
  }
});
